    output  logic [7:0]  axil_periph1_axi_awid,
    output  logic [31:0]  axil_periph1_axi_awaddr,
    output  logic [7:0]  axil_periph1_axi_awlen,
    output  logic [2:0]  axil_periph1_axi_awsize,
    output  logic [1:0]  axil_periph1_axi_awburst,
    output  logic         axil_periph1_axi_awlock,
    output  logic [3:0]  axil_periph1_axi_awcache,
    output  logic [2:0]  axil_periph1_axi_awprot,
    output  logic [3:0]  axil_periph1_axi_awqos,
    output  logic [3:0]  axil_periph1_axi_awregion,
    output  logic         axil_periph1_axi_awuser,
    output  logic         axil_periph1_axi_awvalid,
