    input  logic         axil_periph1_axi_buser,
    input  logic         axil_periph1_axi_bvalid,
    output  logic         axil_periph1_axi_bready,

    output  logic [7:0]  axil_periph1_axi_arid,
    output  logic [31:0]  axil_periph1_axi_araddr,
    output  logic [7:0]  axil_periph1_axi_arlen,
    output  logic [2:0]  axil_periph1_axi_arsize,
    output  logic [1:0]  axil_periph1_axi_arburst,
    output  logic         axil_periph1_axi_arlock,
    output  logic [3:0]  axil_periph1_axi_arcache,
    output  logic [2:0]  axil_periph1_axi_arprot,
    output  logic [3:0]  axil_periph1_axi_arqos,
    output  logic [3:0]  axil_periph1_axi_arregion,
    output  logic         axil_periph1_axi_aruser,
    output  logic         axil_periph1_axi_arvalid,
    input  logic         axil_periph1_axi_arready,

    input  logic [7:0]  axil_periph1_axi_rid,
    input  logic [31:0]  axil_periph1_axi_rdata,
    input  logic [1:0]  axil_periph1_axi_rresp,
    input  logic         axil_periph1_axi_rlast,
    input  logic         axil_periph1_axi_ruser,
    input  logic         axil_periph1_axi_rvalid,
    output  logic         axil_periph1_axi_rready,

    // Slave 5: apb_periph0
    output logic [BRIDGE_ID_WIDTH-1:0] apb_periph0_axi_bridge_id_aw,
    input  logic [BRIDGE_ID_WIDTH-1:0] apb_periph0_axi_bid_bridge_id,
    input  logic                       apb_periph0_axi_bid_valid,

    output logic [BRIDGE_ID_WIDTH-1:0] apb_periph0_axi_bridge_id_ar,
    input  logic [BRIDGE_ID_WIDTH-1:0] apb_periph0_axi_rid_bridge_id,
    input  logic                       apb_periph0_axi_rid_valid,

    output  logic [7:0]  apb_periph0_axi_awid,
    output  logic [31:0]  apb_periph0_axi_awaddr,
    output  logic [7:0]  apb_periph0_axi_awlen,
    output  logic [2:0]  apb_periph0_axi_awsize,
    output  logic [1:0]  apb_periph0_axi_awburst,
    output  logic         apb_periph0_axi_awlock,
    output  logic [3:0]  apb_periph0_axi_awcache,
    output  logic [2:0]  apb_periph0_axi_awprot,
    output  logic [3:0]  apb_periph0_axi_awqos,
    output  logic [3:0]  apb_periph0_axi_awregion,
    output  logic         apb_periph0_axi_awuser,
    output  logic         apb_periph0_axi_awvalid,
    input  logic         apb_periph0_axi_awready,

    output  logic [31:0]  apb_periph0_axi_wdata,
    output  logic [3:0]  apb_periph0_axi_wstrb,
    output  logic         apb_periph0_axi_wlast,
    output  logic         apb_periph0_axi_wuser,
    output  logic         apb_periph0_axi_wvalid,
    input  logic         apb_periph0_axi_wready,

    input  logic [7:0]  apb_periph0_axi_bid,
    input  logic [1:0]  apb_periph0_axi_bresp,
    input  logic         apb_periph0_axi_buser,
    input  logic         apb_periph0_axi_bvalid,
    output  logic         apb_periph0_axi_bready,

    output  logic [7:0]  apb_periph0_axi_arid,
    output  logic [31:0]  apb_periph0_axi_araddr,
    output  logic [7:0]  apb_periph0_axi_arlen,
    output  logic [2:0]  apb_periph0_axi_arsize,
    output  logic [1:0]  apb_periph0_axi_arburst,
    output  logic         apb_periph0_axi_arlock,
    output  logic [3:0]  apb_periph0_axi_arcache,
    output  logic [2:0]  apb_periph0_axi_arprot,
    output  logic [3:0]  apb_periph0_axi_arqos,
    output  logic [3:0]  apb_periph0_axi_arregion,
    output  logic         apb_periph0_axi_aruser,
    output  logic         apb_periph0_axi_arvalid,
    input  logic         apb_periph0_axi_arready,

    input  logic [7:0]  apb_periph0_axi_rid,
    input  logic [31:0]  apb_periph0_axi_rdata,
    input  logic [1:0]  apb_periph0_axi_rresp,
    input  logic         apb_periph0_axi_rlast,
    input  logic         apb_periph0_axi_ruser,
    input  logic         apb_periph0_axi_rvalid,
    output  logic         apb_periph0_axi_rready
);

    // ================================================================
    // Crossbar Routing
    // ================================================================

    // W-follow declarations (assigned below)
    logic cpu_32b_w_to_axil_periph0;
    logic cpu_32b_w_sel_axil_periph0;
    logic cpu_32b_w_to_axil_periph1;
    logic cpu_32b_w_sel_axil_periph1;
    logic cpu_32b_w_to_apb_periph0;
    logic cpu_32b_w_sel_apb_periph0;
    logic cpu_64b_w_to_scratch;
    logic cpu_64b_w_sel_scratch;
    logic cpu_128b_w_to_ddr1;
    logic cpu_128b_w_sel_ddr1;
    logic cpu_256b_w_to_ddr0;
    logic cpu_256b_w_sel_ddr0;
    logic dma0_32b_w_to_axil_periph0;
    logic dma0_32b_w_sel_axil_periph0;
    logic dma0_64b_w_to_scratch;
    logic dma0_64b_w_sel_scratch;
    logic dma0_128b_w_to_ddr1;
    logic dma0_128b_w_sel_ddr1;
    logic dma0_256b_w_to_ddr0;
    logic dma0_256b_w_sel_ddr0;
    logic dma1_32b_w_to_axil_periph1;
    logic dma1_32b_w_sel_axil_periph1;
    logic dma1_64b_w_to_scratch;
    logic dma1_64b_w_sel_scratch;
    logic dma1_128b_w_to_ddr1;
    logic dma1_128b_w_sel_ddr1;
    logic dma1_256b_w_to_ddr0;
    logic dma1_256b_w_sel_ddr0;

    // ================================================================
    // Slave 0: ddr0 (256b)
    // ================================================================
    // Multi-master (3 masters) → ddr0
    //   - cpu (rw)
    //   - dma0 (rw)
    //   - dma1 (rw)

    wire cpu_256b_aw_to_ddr0 = (cpu_256b_aw.addr <= 32'h3fffffff);
    wire cpu_256b_ar_to_ddr0 = (cpu_256b_ar.addr <= 32'h3fffffff);
    wire dma0_256b_aw_to_ddr0 = (dma0_256b_aw.addr <= 32'h3fffffff);
    wire dma0_256b_ar_to_ddr0 = (dma0_256b_ar.addr <= 32'h3fffffff);
    wire dma1_256b_aw_to_ddr0 = (dma1_256b_aw.addr <= 32'h3fffffff);
    wire dma1_256b_ar_to_ddr0 = (dma1_256b_ar.addr <= 32'h3fffffff);

    // ---- AW arbiter for ddr0: round-robin, lock until handshake ----
    logic [2:0] ddr0_aw_arb_req;
    assign ddr0_aw_arb_req = {dma1_256b_aw_to_ddr0 && dma1_256b_awvalid, dma0_256b_aw_to_ddr0 && dma0_256b_awvalid, cpu_256b_aw_to_ddr0 && cpu_256b_awvalid};
    logic [1:0] ddr0_aw_arb_lock, ddr0_aw_arb_rr;
    logic ddr0_aw_arb_locked;
    wire [1:0] ddr0_aw_arb_pick = (ddr0_aw_arb_rr == 2'd0) ? (ddr0_aw_arb_req[0] ? 2'd0 : ddr0_aw_arb_req[1] ? 2'd1 : 2'd2) : 
        (ddr0_aw_arb_rr == 2'd1) ? (ddr0_aw_arb_req[1] ? 2'd1 : ddr0_aw_arb_req[2] ? 2'd2 : 2'd0) : 
        ddr0_aw_arb_req[2] ? 2'd2 : ddr0_aw_arb_req[0] ? 2'd0 : 2'd1;
    wire ddr0_aw_arb_gnt_valid = ddr0_aw_arb_locked || (|ddr0_aw_arb_req);
    wire [1:0] ddr0_aw_arb_gnt = ddr0_aw_arb_locked ? ddr0_aw_arb_lock : ddr0_aw_arb_pick;
    always_ff @(posedge aclk or negedge aresetn) begin
        if (!aresetn) begin
            ddr0_aw_arb_lock   <= '0;
            ddr0_aw_arb_rr     <= '0;
            ddr0_aw_arb_locked <= 1'b0;
        end else begin
            if (ddr0_axi_awvalid && ddr0_axi_awready) begin
                ddr0_aw_arb_locked <= 1'b0;
                ddr0_aw_arb_rr <= (ddr0_aw_arb_gnt == 2'd2) ? 2'd0 : ddr0_aw_arb_gnt + 1'b1;
            end else if (ddr0_axi_awvalid) begin
                ddr0_aw_arb_lock   <= ddr0_aw_arb_gnt;
                ddr0_aw_arb_locked <= 1'b1;
            end
        end
    end
    wire cpu_256b_aw_gnt_ddr0 = ddr0_aw_arb_gnt_valid && (ddr0_aw_arb_gnt == 2'd0) && ddr0_aw_arb_req[0];
    wire dma0_256b_aw_gnt_ddr0 = ddr0_aw_arb_gnt_valid && (ddr0_aw_arb_gnt == 2'd1) && ddr0_aw_arb_req[1];
    wire dma1_256b_aw_gnt_ddr0 = ddr0_aw_arb_gnt_valid && (ddr0_aw_arb_gnt == 2'd2) && ddr0_aw_arb_req[2];

    // AW channel (arbitrated mux across writing masters)
    assign ddr0_axi_awid = (cpu_256b_aw_gnt_ddr0 ? cpu_256b_aw.id : '0) |
        (dma0_256b_aw_gnt_ddr0 ? dma0_256b_aw.id : '0) |
        (dma1_256b_aw_gnt_ddr0 ? dma1_256b_aw.id : '0);
    assign ddr0_axi_awaddr = (cpu_256b_aw_gnt_ddr0 ? cpu_256b_aw.addr : '0) |
        (dma0_256b_aw_gnt_ddr0 ? dma0_256b_aw.addr : '0) |
        (dma1_256b_aw_gnt_ddr0 ? dma1_256b_aw.addr : '0);
    assign ddr0_axi_awlen = (cpu_256b_aw_gnt_ddr0 ? cpu_256b_aw.len : '0) |
        (dma0_256b_aw_gnt_ddr0 ? dma0_256b_aw.len : '0) |
        (dma1_256b_aw_gnt_ddr0 ? dma1_256b_aw.len : '0);
    assign ddr0_axi_awsize = (cpu_256b_aw_gnt_ddr0 ? cpu_256b_aw.size : '0) |
        (dma0_256b_aw_gnt_ddr0 ? dma0_256b_aw.size : '0) |
        (dma1_256b_aw_gnt_ddr0 ? dma1_256b_aw.size : '0);
    assign ddr0_axi_awburst = (cpu_256b_aw_gnt_ddr0 ? cpu_256b_aw.burst : '0) |
        (dma0_256b_aw_gnt_ddr0 ? dma0_256b_aw.burst : '0) |
        (dma1_256b_aw_gnt_ddr0 ? dma1_256b_aw.burst : '0);
    assign ddr0_axi_awlock = (cpu_256b_aw_gnt_ddr0 ? cpu_256b_aw.lock : '0) |
        (dma0_256b_aw_gnt_ddr0 ? dma0_256b_aw.lock : '0) |
        (dma1_256b_aw_gnt_ddr0 ? dma1_256b_aw.lock : '0);
    assign ddr0_axi_awcache = (cpu_256b_aw_gnt_ddr0 ? cpu_256b_aw.cache : '0) |
        (dma0_256b_aw_gnt_ddr0 ? dma0_256b_aw.cache : '0) |
        (dma1_256b_aw_gnt_ddr0 ? dma1_256b_aw.cache : '0);
    assign ddr0_axi_awprot = (cpu_256b_aw_gnt_ddr0 ? cpu_256b_aw.prot : '0) |
        (dma0_256b_aw_gnt_ddr0 ? dma0_256b_aw.prot : '0) |
        (dma1_256b_aw_gnt_ddr0 ? dma1_256b_aw.prot : '0);
    assign ddr0_axi_awvalid = cpu_256b_aw_gnt_ddr0 || dma0_256b_aw_gnt_ddr0 || dma1_256b_aw_gnt_ddr0;

    // W owner FIFO: slave-side AW accept order owns the W channel
    logic [1:0] ddr0_wowner_mem [16];
    logic [4:0] ddr0_wowner_wptr, ddr0_wowner_rptr;
    always_ff @(posedge aclk or negedge aresetn) begin
        if (!aresetn) begin
            ddr0_wowner_wptr <= '0;
            ddr0_wowner_rptr <= '0;
        end else begin
            if (ddr0_axi_awvalid && ddr0_axi_awready) begin
                ddr0_wowner_mem[ddr0_wowner_wptr[3:0]] <= ddr0_aw_arb_gnt;
                ddr0_wowner_wptr <= ddr0_wowner_wptr + 1'b1;
            end
            if (ddr0_axi_wvalid && ddr0_axi_wready && ddr0_axi_wlast) begin
                ddr0_wowner_rptr <= ddr0_wowner_rptr + 1'b1;
            end
        end
    end
    wire ddr0_wowner_valid = (ddr0_wowner_wptr != ddr0_wowner_rptr);
    wire [1:0] ddr0_wowner_head = ddr0_wowner_mem[ddr0_wowner_rptr[3:0]];
    assign cpu_256b_w_sel_ddr0 = ddr0_wowner_valid && (ddr0_wowner_head == 2'd0) && cpu_256b_w_to_ddr0;
    assign dma0_256b_w_sel_ddr0 = ddr0_wowner_valid && (ddr0_wowner_head == 2'd1) && dma0_256b_w_to_ddr0;
    assign dma1_256b_w_sel_ddr0 = ddr0_wowner_valid && (ddr0_wowner_head == 2'd2) && dma1_256b_w_to_ddr0;

    // W channel (owner-gated mux across writing masters)
    assign ddr0_axi_wdata = ((cpu_256b_w_sel_ddr0 && cpu_256b_wvalid) ? cpu_256b_w.data : '0) |
        ((dma0_256b_w_sel_ddr0 && dma0_256b_wvalid) ? dma0_256b_w.data : '0) |
        ((dma1_256b_w_sel_ddr0 && dma1_256b_wvalid) ? dma1_256b_w.data : '0);
    assign ddr0_axi_wstrb = ((cpu_256b_w_sel_ddr0 && cpu_256b_wvalid) ? cpu_256b_w.strb : '0) |
        ((dma0_256b_w_sel_ddr0 && dma0_256b_wvalid) ? dma0_256b_w.strb : '0) |
        ((dma1_256b_w_sel_ddr0 && dma1_256b_wvalid) ? dma1_256b_w.strb : '0);
    assign ddr0_axi_wlast = ((cpu_256b_w_sel_ddr0 && cpu_256b_wvalid) ? cpu_256b_w.last : '0) |
        ((dma0_256b_w_sel_ddr0 && dma0_256b_wvalid) ? dma0_256b_w.last : '0) |
        ((dma1_256b_w_sel_ddr0 && dma1_256b_wvalid) ? dma1_256b_w.last : '0);
    assign ddr0_axi_wvalid = (cpu_256b_w_sel_ddr0 && cpu_256b_wvalid) || (dma0_256b_w_sel_ddr0 && dma0_256b_wvalid) || (dma1_256b_w_sel_ddr0 && dma1_256b_wvalid);

    // Bready (slave → owning master, by bid_bridge_id)
    assign ddr0_axi_bready = ((ddr0_axi_bid_bridge_id == 0) && ddr0_axi_bid_valid ? cpu_256b_bready : '0) |
        ((ddr0_axi_bid_bridge_id == 1) && ddr0_axi_bid_valid ? dma0_256b_bready : '0) |
        ((ddr0_axi_bid_bridge_id == 2) && ddr0_axi_bid_valid ? dma1_256b_bready : '0);

    // Bridge ID (writes) — the granted master's id
    assign ddr0_axi_bridge_id_aw = (cpu_256b_aw_gnt_ddr0 ? cpu_bridge_id_aw : '0) |
        (dma0_256b_aw_gnt_ddr0 ? dma0_bridge_id_aw : '0) |
        (dma1_256b_aw_gnt_ddr0 ? dma1_bridge_id_aw : '0);

    // ---- AR arbiter for ddr0: round-robin, lock until handshake ----
    logic [2:0] ddr0_ar_arb_req;
    assign ddr0_ar_arb_req = {dma1_256b_ar_to_ddr0 && dma1_256b_arvalid, dma0_256b_ar_to_ddr0 && dma0_256b_arvalid, cpu_256b_ar_to_ddr0 && cpu_256b_arvalid};
    logic [1:0] ddr0_ar_arb_lock, ddr0_ar_arb_rr;
    logic ddr0_ar_arb_locked;
    wire [1:0] ddr0_ar_arb_pick = (ddr0_ar_arb_rr == 2'd0) ? (ddr0_ar_arb_req[0] ? 2'd0 : ddr0_ar_arb_req[1] ? 2'd1 : 2'd2) : 
        (ddr0_ar_arb_rr == 2'd1) ? (ddr0_ar_arb_req[1] ? 2'd1 : ddr0_ar_arb_req[2] ? 2'd2 : 2'd0) : 
        ddr0_ar_arb_req[2] ? 2'd2 : ddr0_ar_arb_req[0] ? 2'd0 : 2'd1;
    wire ddr0_ar_arb_gnt_valid = ddr0_ar_arb_locked || (|ddr0_ar_arb_req);
    wire [1:0] ddr0_ar_arb_gnt = ddr0_ar_arb_locked ? ddr0_ar_arb_lock : ddr0_ar_arb_pick;
    always_ff @(posedge aclk or negedge aresetn) begin
        if (!aresetn) begin
            ddr0_ar_arb_lock   <= '0;
            ddr0_ar_arb_rr     <= '0;
            ddr0_ar_arb_locked <= 1'b0;
        end else begin
            if (ddr0_axi_arvalid && ddr0_axi_arready) begin
                ddr0_ar_arb_locked <= 1'b0;
                ddr0_ar_arb_rr <= (ddr0_ar_arb_gnt == 2'd2) ? 2'd0 : ddr0_ar_arb_gnt + 1'b1;
            end else if (ddr0_axi_arvalid) begin
                ddr0_ar_arb_lock   <= ddr0_ar_arb_gnt;
                ddr0_ar_arb_locked <= 1'b1;
            end
        end
    end
    wire cpu_256b_ar_gnt_ddr0 = ddr0_ar_arb_gnt_valid && (ddr0_ar_arb_gnt == 2'd0) && ddr0_ar_arb_req[0];
    wire dma0_256b_ar_gnt_ddr0 = ddr0_ar_arb_gnt_valid && (ddr0_ar_arb_gnt == 2'd1) && ddr0_ar_arb_req[1];
    wire dma1_256b_ar_gnt_ddr0 = ddr0_ar_arb_gnt_valid && (ddr0_ar_arb_gnt == 2'd2) && ddr0_ar_arb_req[2];

    // AR channel (arbitrated mux across reading masters)
    assign ddr0_axi_arid = (cpu_256b_ar_gnt_ddr0 ? cpu_256b_ar.id : '0) |
        (dma0_256b_ar_gnt_ddr0 ? dma0_256b_ar.id : '0) |
        (dma1_256b_ar_gnt_ddr0 ? dma1_256b_ar.id : '0);
    assign ddr0_axi_araddr = (cpu_256b_ar_gnt_ddr0 ? cpu_256b_ar.addr : '0) |
        (dma0_256b_ar_gnt_ddr0 ? dma0_256b_ar.addr : '0) |
        (dma1_256b_ar_gnt_ddr0 ? dma1_256b_ar.addr : '0);
    assign ddr0_axi_arlen = (cpu_256b_ar_gnt_ddr0 ? cpu_256b_ar.len : '0) |
        (dma0_256b_ar_gnt_ddr0 ? dma0_256b_ar.len : '0) |
        (dma1_256b_ar_gnt_ddr0 ? dma1_256b_ar.len : '0);
    assign ddr0_axi_arsize = (cpu_256b_ar_gnt_ddr0 ? cpu_256b_ar.size : '0) |
        (dma0_256b_ar_gnt_ddr0 ? dma0_256b_ar.size : '0) |
        (dma1_256b_ar_gnt_ddr0 ? dma1_256b_ar.size : '0);
    assign ddr0_axi_arburst = (cpu_256b_ar_gnt_ddr0 ? cpu_256b_ar.burst : '0) |
        (dma0_256b_ar_gnt_ddr0 ? dma0_256b_ar.burst : '0) |
        (dma1_256b_ar_gnt_ddr0 ? dma1_256b_ar.burst : '0);
    assign ddr0_axi_arlock = (cpu_256b_ar_gnt_ddr0 ? cpu_256b_ar.lock : '0) |
        (dma0_256b_ar_gnt_ddr0 ? dma0_256b_ar.lock : '0) |
        (dma1_256b_ar_gnt_ddr0 ? dma1_256b_ar.lock : '0);
    assign ddr0_axi_arcache = (cpu_256b_ar_gnt_ddr0 ? cpu_256b_ar.cache : '0) |
        (dma0_256b_ar_gnt_ddr0 ? dma0_256b_ar.cache : '0) |
        (dma1_256b_ar_gnt_ddr0 ? dma1_256b_ar.cache : '0);
    assign ddr0_axi_arprot = (cpu_256b_ar_gnt_ddr0 ? cpu_256b_ar.prot : '0) |
        (dma0_256b_ar_gnt_ddr0 ? dma0_256b_ar.prot : '0) |
        (dma1_256b_ar_gnt_ddr0 ? dma1_256b_ar.prot : '0);
    assign ddr0_axi_arvalid = cpu_256b_ar_gnt_ddr0 || dma0_256b_ar_gnt_ddr0 || dma1_256b_ar_gnt_ddr0;

    // Rready (slave → owning master, by rid_bridge_id)
    assign ddr0_axi_rready = ((ddr0_axi_rid_bridge_id == 0) && ddr0_axi_rid_valid ? cpu_256b_rready : '0) |
